// Signed Distance to Equilateral Triangle (Pointing Up)
// p: coordinates (centered)
// r: circumradius (distance from center to vertices)
float sdEquilateralTriangle(float2 p, float r) {
    const float k = 1.73205080757; // sqrt(3)
    p.x = abs(p.x); // Symmetry

    // Define vertices based on radius r
    // Top vertex at (0, r)
    // Bottom-right vertex at (r*sqrt(3)/2, -r/2)
    float2 v1 = float2(0.0, r);
    float2 v2 = float2(r * k * 0.5, -0.5 * r);

    // Distance to Slanted Edge (v1 -> v2)
    float2 e1 = v2 - v1;
    float2 w1 = p - v1;
    // Ensure non-zero length for stability
    float e1sq = dot(e1, e1);
    float2 d1_vec = w1 - e1 * clamp(dot(w1, e1) / (e1sq + 1e-8), 0.0, 1.0);
    float d1_sq = dot(d1_vec, d1_vec);

    // Distance to Bottom Edge (Horizontal segment)
    // Segment from (0, -0.5r) to (v2.x, -0.5r) due to symmetry
    float2 e2 = float2(v2.x, 0.0);
    float2 w2 = p - float2(0.0, -0.5 * r);
    float e2sq = dot(e2, e2);
    float2 d2_vec = w2 - e2 * clamp(dot(w2, e2) / (e2sq + 1e-8), 0.0, 1.0);
    float d2_sq = dot(d2_vec, d2_vec);

    // Minimum distance (Squared then Sqrt)
    float d = sqrt(min(d1_sq, d2_sq));

    // Sign calculation (Negative is inside)
    // We are inside if we are below the slanted edge AND above the bottom edge.
    // Slant Normal (unnormalized direction): (1.5, k/2)
    // This vector points OUTWARDS relative to the triangle center.
    float s1 = dot(p - v1, float2(1.5, k * 0.5)); 
    // Bottom Normal: (0, -1)
    float s2 = -p.y - 0.5 * r;

    // Outside if any dot product with outward normals is > 0
    return d * sign(max(s1, s2));
}

void EquilateralTriangle_float(float2 UV, float Size, float4 Color, out float4 outColor) {
    // Center UVs
    float2 centered = UV - 0.5;

    // Ensure radius is non-negative and non-zero to prevent div/0 errors
    float r = max(Size, 0.0001);

    // Calculate Signed Distance
    float d = sdEquilateralTriangle(centered, r);

    // Anti-aliasing
    // Use smoothstep centered on the edge (0.0) based on screen-space derivative
    float delta = fwidth(d);
    float alpha = 1.0 - smoothstep(-delta, delta, d);

    // Output Color blended with alpha mask
    outColor = float4(Color.rgb, Color.a * alpha);
